revoke all on function private.tasting_catalog_v2() from public;

create function public.save_tasting_note(
  p_record_id uuid, p_operation_id uuid, p_expected_revision integer,
  p_mode public.note_mode, p_catalog_version integer, p_answers jsonb, p_note text, p_edited boolean
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  owner_id uuid := auth.uid(); existing public.tasting_records;
  previous public.record_notes; payload jsonb; contract jsonb; answer jsonb; field jsonb;
  codes text[]; answer_id text; state text; strength integer; parent text;
begin
  if owner_id is null or not private.active_user() then raise exception 'Authentication required' using errcode='42501'; end if;
  select * into existing from public.tasting_records where id=p_record_id and user_id=owner_id for update;
  if not found then raise exception 'Record not found' using errcode='42501'; end if;
  if p_operation_id is null or p_catalog_version is distinct from 2 or p_mode is null or p_edited is null
    or p_note is null or char_length(btrim(p_note))=0 or char_length(p_note)>10000
    or jsonb_typeof(p_answers) is distinct from 'array' or jsonb_array_length(p_answers)>150 or octet_length(p_answers::text)>100000
    then raise exception 'Invalid note input' using errcode='23514'; end if;
  payload:=jsonb_build_object('mode',p_mode,'catalog',p_catalog_version,'answers',p_answers,'note',p_note,'edited',p_edited);
  select * into previous from public.record_notes where record_id=p_record_id and user_id=owner_id;
  if previous.last_operation_id=p_operation_id then
    if previous.last_save_payload is distinct from payload then raise exception 'Operation payload changed' using errcode='23505'; end if;
    return jsonb_build_object('recordId',p_record_id,'revision',existing.revision,'replayed',true);
  end if;
  if existing.revision is distinct from p_expected_revision then raise exception 'Record changed; reload before editing' using errcode='40001'; end if;
  contract:=private.tasting_catalog_v2()->(existing.category::text||'.'||p_mode::text);
  if contract is null then raise exception 'Unsupported category' using errcode='23514'; end if;
  if (select count(*) from jsonb_array_elements(p_answers)) <> (select count(distinct x->>'questionId') from jsonb_array_elements(p_answers) x)
    then raise exception 'Duplicate answer' using errcode='23514'; end if;
  for answer in select * from jsonb_array_elements(p_answers) loop
    answer_id:=answer->>'questionId'; field:=contract->answer_id; state:=answer->>'status';
    if field is null or state is null or state not in ('unanswered','skipped','unknown','none','answered')
      or jsonb_typeof(answer->'descriptorCodes') is distinct from 'array'
      or (answer->'freeText' is not null and jsonb_typeof(answer->'freeText') not in ('string','null'))
      or char_length(coalesce(answer->>'freeText',''))>2000
      then raise exception 'Invalid answer' using errcode='23514'; end if;
    codes:=array(select jsonb_array_elements_text(answer->'descriptorCodes'));
    if cardinality(codes) > (field->>'max')::integer or cardinality(codes)<>(select count(distinct x) from unnest(codes) x)
      or exists(select 1 from unnest(codes) code where not (field->'codes') ? code)
      then raise exception 'Invalid descriptor' using errcode='23514'; end if;
    strength:=(answer->>'intensity')::integer;
    if strength is not null and (strength<0 or strength>5 or cardinality(codes)<>1 or field->'intensities'->>codes[1] is null
      or strength<>(field->'intensities'->>codes[1])::integer)
      then raise exception 'Invalid intensity' using errcode='23514'; end if;
    if cardinality(codes)=1 and field->'intensities'->>codes[1] is not null
      and strength is distinct from (field->'intensities'->>codes[1])::integer
      then raise exception 'Missing intensity' using errcode='23514'; end if;
    if state='none' and not (field->'codes') ? 'none' then raise exception 'Unsupported absence answer' using errcode='23514'; end if;
    if state<>'answered' and (cardinality(codes)>0 or strength is not null or coalesce(answer->>'freeText','')<>'')
      then raise exception 'Non-answer contains observations' using errcode='23514'; end if;
    if jsonb_typeof(field->'when')='object' and not exists(
      select 1 from jsonb_array_elements(p_answers) a where a->>'questionId'=field->'when'->>'field'
        and a->>'status'='answered' and a->'descriptorCodes' ? (field->'when'->>'includes'))
      then raise exception 'Inactive answer' using errcode='23514'; end if;
    if jsonb_typeof(field->'unless')='object' and exists(
      select 1 from jsonb_array_elements(p_answers) a where a->>'questionId'=field->'unless'->>'field'
        and a->>'status'='answered' and a->'descriptorCodes' ? (field->'unless'->>'includes'))
      then raise exception 'Unobserved answer' using errcode='23514'; end if;
    if field->>'kind'='aroma' then
      for parent in select code from unnest(codes) code where code like 'detail.%' loop
        if not ('family.'||split_part(parent,'.',2))=any(codes) then raise exception 'Inactive aroma detail' using errcode='23514'; end if;
      end loop;
    end if;
  end loop;
  insert into public.record_notes(record_id,user_id,mode,catalog_version)
    values(p_record_id,owner_id,p_mode,p_catalog_version)
    on conflict(record_id) do update set mode=p_mode,catalog_version=p_catalog_version;
  delete from public.record_answers where record_id=p_record_id and user_id=owner_id and mode=p_mode and catalog_version=p_catalog_version;
  for answer in select * from jsonb_array_elements(p_answers) loop
    insert into public.record_answers(user_id,record_id,mode,catalog_version,question_id,status,descriptor_codes,intensity,free_text)
      values(owner_id,p_record_id,p_mode,p_catalog_version,answer->>'questionId',(answer->>'status')::public.answer_status,
        array(select jsonb_array_elements_text(answer->'descriptorCodes')),(answer->>'intensity')::smallint,answer->>'freeText');
  end loop;
  update public.record_notes set confirmed_note=p_note,edited_by_user=p_edited,confirmed_input_revision=input_revision,
    last_operation_id=p_operation_id,last_save_payload=payload where record_id=p_record_id and user_id=owner_id;
  insert into public.user_settings(user_id,last_note_mode) values(owner_id,p_mode)
    on conflict(user_id) do update set last_note_mode=p_mode;
  return jsonb_build_object('recordId',p_record_id,'revision',(select revision from public.tasting_records where id=p_record_id),'replayed',false);
end;
$$;
revoke all on function public.save_tasting_note(uuid,uuid,integer,public.note_mode,integer,jsonb,text,boolean) from public,anon;
grant execute on function public.save_tasting_note(uuid,uuid,integer,public.note_mode,integer,jsonb,text,boolean) to authenticated;

-- Confirmed answers/prose must share the atomic RPC and optimistic revision checks.
revoke insert,update,delete on public.record_answers from authenticated;
revoke insert (record_id,user_id,mode,catalog_version,input_revision,confirmed_note,edited_by_user),
  update (mode,catalog_version,confirmed_note,edited_by_user) on public.record_notes from authenticated;
revoke delete on public.record_notes from authenticated;
